head.script:
///////// 1. 변수 및 선언 영역 /////////
// 원본 : /lstproc/ULDSTF05918.gfm (ELW 최종거래일에 의한 상장폐지 팝업)
/*
 * 화면 동작
 *  - 부모(ULDSTF05916 상장폐지)가 넘긴 업무처리번호가 없으면 신규, 있으면 수정이다.
 *  - 신규: 현재일(기준일)로 [조회]하면 다음 영업일이 최종거래일인 ELW 종목과 안내문구용 일자를 받아
 *          상장폐지일·기타 안내문을 채운다. 사유는 최종거래일 도래(690014)가 기본이다.
 *  - 수정: 업무처리번호로 상세(MST)·대상종목을 조회하고, 상장폐지일이 지났으면 처리 버튼을 잠근다.
 *  - 등록·수정·삭제·공시안내문작성(ULDSTF92024). 통신·데이터 정의는 ULDSTF05918_API.md 명세 기준.
 * 업무 분석 : conversion/conversion-front/ui/ULDSTF05918/ULDSTF05918.md (§번호는 이 문서의 절)
 */

// 부모 화면에서 넘겨받는 값 (§1.2)
scwin.secugrpId = "";       // 증권그룹ID (AS-IS arr[0]) — 이 화면에서는 쓰지 않음
scwin.mktId = "";           // 시장구분코드 (AS-IS arr[1]) — AS-IS 는 사유 목록 조회 조건(§10 #1)
scwin.bzProcsNo = "";       // 업무처리번호 (AS-IS arr[2]) — 비어 있으면 신규, 있으면 수정
scwin.baseDd = "";          // 기준일 (AS-IS arr[3]) — 신규는 오늘, 수정은 최종거래일

// 화면 상태값
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제
scwin.curDate = "";         // 서버 현재일 (yyyyMMdd)
scwin.savedState = "";      // 조회 직후 입력값 — 안내문작성 전 미저장 변경 확인용 (§6.8)

// 고정값
scwin.ELW_ISUR_CD = "99999";            // ELW 상장폐지 발행기관코드 — 원본이 신규 등록·안내문작성에 고정으로 넘기던 값
scwin.DEFAULT_RSN_CD = "690014";        // 신규 기본 상장폐지사유 — 최종거래일 도래
// TODO: 상장폐지사유 목록 API 명세 없음 — 원본 listCode(MKT=시장구분, RSN=05) 대체 API 가 오면 조회로 바꾼다 (§10 #1)
scwin.RSN_LIST = [
    { code : "690014", name : "최종거래일 도래", regl : "유가증권시장상장규정 제143조" }
];
scwin.DSCL_FORM_CD = "68955C";          // 공시안내문 서식코드 (AS-IS arr[0])
scwin.DSCL_MKT_ID = "1";                // 공시안내문 시장구분 (AS-IS arr[3])
scwin.DSCL_TITLE = "익일 최종거래일에 의한 상장폐지예고";   // 공시제목 (AS-IS arr[5])

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 29
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05918.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 29
 * @description 로딩 — 버튼 잠금 → 파라미터 수신 → 달력·Enter 키 바인딩 → 사유 목록 → 신규 준비 또는 수정 조회. (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 로딩 동안 버튼 잠금 — 조회가 예외로 끝나도 버튼이 XML 기본값(전부 활성)으로 남지 않게 한다.
    scwin.lockButtons();

    // 2) 파라미터 수신 — 원본 frame.Provider("../").fn_GetPar(arrPar) (§1.2)
    const param = $c.data.getParameter() ?? {};

    scwin.secugrpId = param.secugrpId ?? "";    // AS-IS arr[0]
    scwin.mktId = param.mktId ?? "";            // AS-IS arr[1]
    scwin.bzProcsNo = param.bzProcsNo ?? "";    // AS-IS arr[2]
    scwin.baseDd = param.baseDd ?? "";          // AS-IS arr[3]

    // 3) 달력 검사(규칙 37)·조회 영역 Enter 키(규칙 22)
    $c.date.checkCalendarFormat(edt_Dd, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_DelistDd, "yyyyMMdd");
    $c.win.setEnterKeyEvent(panel_1, scwin.btn_Search_onclick);
    scwin.curDate = $c.date.getServerDateTime("yyyyMMdd");

    // 4) 사유 목록·기준일 — 원본 fn_get_rsn_cd, edt_Dd.text = Dd
    dlt_rsn.setJSON(scwin.RSN_LIST);
    dma_search.set("baseDd", scwin.baseDd);

    // 5) 업무처리번호 유무로 신규 준비 또는 수정 조회
    if (scwin.isNew()) {
        scwin.initNewForm();
    } else {
        await scwin.selectDetail();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 조회 클릭(조회 영역 Enter 키 포함) — 신규일 때만 최종거래일 도래 종목을 조회한다. (§6.2, §1.4 업무 2)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        await scwin.searchNewIsu();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05918.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.cmb_Rsn_Cd_onviewchange
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상장폐지사유를 사용자가 바꾸면 그 사유의 근거규정을 채운다. (원본 cmb_Rsn_Cd OnSelChange2 — §6.4)
 * 사용자 조작에만 발생하므로 원본의 isFirstLoad 가드는 필요 없다.
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.cmb_Rsn_Cd_onviewchange = async function (info) {
    try {
        scwin.applyGrndRegul();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05918.cmb_Rsn_Cd_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05918.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 수정 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05918.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Delete_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 삭제 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05918.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Dscl_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 안내문작성 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Dscl_onclick = async function (e) {
    try {
        await scwin.writeDscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05918.btn_Dscl_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectNewIsu
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규: 기준일 다음 영업일이 최종거래일인 ELW 종목을 조회한다. (원본 fn_get_isu_cd — §5.1)
 * @param {String} baseDd 기준일 (yyyyMMdd)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectNewIsu = async function (baseDd) {
    const sbmOptions = {
        id : "sbm_selectNewIsu",
        method : "get",
        action : "/api/listing/lstproc/elw/delisting/detail/select-new-isu-last-trading-day",
        // 명세 target 은 dlt_newIsuLastTradingDay — 컬럼이 같은 그리드 목록 dlt_isu 로 받는다 (§5)
        target : "dlt_isu=body",
        gridview : "grd_isu",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { baseDd : baseDd });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    return Boolean(result.responseJSON?.success);
};

/**
 * @method
 * @name scwin.selectLastTradingDayInfo
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규: 기준일로 상장폐지일과 기타 안내문구용 일자 표기를 조회한다. (원본 fn_getCheckDD — §5.2)
 * @param {String} baseDd 기준일 (yyyyMMdd)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectLastTradingDayInfo = async function (baseDd) {
    const sbmOptions = {
        id : "sbm_selectLastTradingDayInfo",
        method : "get",
        action : "/api/listing/lstproc/elw/delisting/detail/select-last-trading-day-info",
        target : "dma_lastTradingDayInfo=body",
        isProcessMsg : false
    };

    dma_lastTradingDayInfo.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, { baseDd : baseDd });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    return Boolean(result.responseJSON?.success);
};

/**
 * @method
 * @name scwin.selectMst
 * @author Inswave
 * @date 2026. 10. 29
 * @description 수정: 업무처리번호로 상장폐지 상세(MST)를 조회한다 — 상장폐지일·사유·근거규정·기타 입력란에 바인딩된다. (원본 fn_search 의 dts_Mst — §5.3)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectMst = async function () {
    const sbmOptions = {
        id : "sbm_selectMst",
        method : "get",
        action : "/api/listing/lstproc/elw/delisting/detail/select-mst",
        target : "dma_mst=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : scwin.bzProcsNo });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    return Boolean(result.responseJSON?.success);
};

/**
 * @method
 * @name scwin.selectIsu
 * @author Inswave
 * @date 2026. 10. 29
 * @description 수정: 업무처리번호로 등록된 상장폐지 대상종목을 조회한다. (원본 fn_search 의 dts_Isu — §5.4)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectIsu = async function () {
    const sbmOptions = {
        id : "sbm_selectIsu",
        method : "get",
        action : "/api/listing/lstproc/elw/delisting/detail/select-isu",
        target : "dlt_isu=body",
        gridview : "grd_isu",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : scwin.bzProcsNo });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    return Boolean(result.responseJSON?.success);
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 29
 * @description 등록(I)·수정(U). 명세 요청 정의(dma_save·dlt_saveIsuList)에 담아 머리는 requestData 최상위, 종목 목록은 isuList 로 보낸다.
 * setJSON 이 정의된 키만 남겨 명세 밖 값은 보내지 않는다. 성공하면 그 업무처리번호로 다시 조회한다. (원본 fn_save_trs + trs — §5.5, §5.6)
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @param {String} bzProcsNo 업무처리번호 (등록은 새로 받은 번호)
 * @returns
 * @hidden N
 */
scwin.saveTrs = async function (trJob, bzProcsNo) {
    const isInsert = (trJob === "I");
    const jobNm = isInsert ? "저장" : "수정";

    // TODO: 원본이 마스터에 넣던 시장조치적용대상구분코드 "1"(종목별)은 요청 정의에 없음 (§10 #5)
    dma_save.setEmptyValue();
    dma_save.setJSON({
        listBzTpCd : $c.lc.glb.LIST_BZ_TP_CD_307,                              // ELW 최종거래일에 의한 상장폐지
        bzProcsNo : bzProcsNo,
        isurCd : isInsert ? scwin.ELW_ISUR_CD : (dma_mst.get("isurCd") || scwin.ELW_ISUR_CD),
        delistDd : dma_mst.get("delistDd"),
        delistRsnCd : dma_mst.get("delistRsnCd"),
        delistRsnDsc : dma_mst.get("delistRsnDsc"),                             // 원본도 화면에서 채우지 않음 (§10 #6)
        ulyDelistRsnCd : dma_mst.get("ulyDelistRsnCd"),
        ulyDelistBzProcsNo : dma_mst.get("ulyDelistBzProcsNo"),
        grndRegulNm : dma_mst.get("grndRegulNm"),
        remk : dma_mst.get("remk")
    });
    dlt_saveIsuList.setJSON(dlt_isu.getAllJSON());

    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : isInsert ? "/api/listing/lstproc/elw/delisting/detail/register" : "/api/listing/lstproc/elw/delisting/detail/modify",
        target : "dma_result=body",
        mediatype : "application/json",
        isProcessMsg : false
        // ref 는 쓰지 않는다 — 명세: 요청 정의 데이터를 requestData 로 전달
    };

    const requestData = {
        ...dma_save.getJSON(),
        isuList : dlt_saveIsuList.getAllJSON()
    };

    dma_result.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!scwin.isComplete(result)) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", jobNm));

    // 원본 trs OnSuccess → fn_search(). 등록은 응답 번호가 있으면 그 번호, 없으면 화면이 받은 번호로 수정 모드 재조회
    scwin.bzProcsNo = String(dma_result.get("bzProcsNo") || bzProcsNo);
    await scwin.selectDetail();
};

/**
 * @method
 * @name scwin.deleteTrs
 * @author Inswave
 * @date 2026. 10. 29
 * @description 삭제. 명세 requestData(listBzTpCd·bzProcsNo·isurCd)로 보내고, 성공하면 팝업을 닫는다 — 부모는 await 가 끝나면 다시 조회한다. (§5.7)
 * @returns
 * @hidden N
 */
scwin.deleteTrs = async function () {
    const sbmOptions = {
        id : "sbm_deleteTrs",
        method : "post",
        action : "/api/listing/lstproc/elw/delisting/detail/remove",
        target : "dma_result=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    const requestData = {
        listBzTpCd : $c.lc.glb.LIST_BZ_TP_CD_307,
        bzProcsNo : scwin.bzProcsNo,
        isurCd : dma_mst.get("isurCd") || scwin.ELW_ISUR_CD
    };

    dma_result.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!scwin.isComplete(result)) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    $c.win.closePopup();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.isNew
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 작성인지 — 업무처리번호가 비어 있으면 신규다.
 * @returns {Boolean} 신규이면 true
 * @hidden N
 */
scwin.isNew = function () {
    return $c.util.isEmpty(scwin.bzProcsNo);
};

/**
 * @method
 * @name scwin.initNewForm
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 준비. 입력과 종목 목록을 비우고 사유를 최종거래일 도래로, 근거규정을 그 사유의 규정으로 채운 뒤 [저장]만 켠다.
 * 현재일은 고칠 수 있고 [조회]를 쓸 수 있다. (원본 fn_new_onload + dts_Mst OnLoadCompleted — §3)
 * @returns
 * @hidden N
 */
scwin.initNewForm = function () {
    dma_mst.setEmptyValue();
    dlt_isu.removeAll();
    dma_mst.set("delistRsnCd", scwin.DEFAULT_RSN_CD);
    scwin.applyGrndRegul();

    edt_Dd.setReadOnly(false);
    btn_Search.setDisabled(false);
    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 10. 29
 * @description 수정 조회. 현재일·[조회]를 잠그고 상세(MST)와 대상종목을 차례로 읽은 뒤, 상장폐지일로 버튼 상태를 정한다.
 * 실패하면 버튼을 모두 잠근다 — 등록 뒤 재조회 실패에 신규 상태([저장] 활성)가 남아 같은 건을 다시 등록하지 않게. (원본 fn_search + dts_Mst OnLoadCompleted — §1.4 업무 1)
 * @returns
 * @hidden N
 */
scwin.selectDetail = async function () {
    edt_Dd.setReadOnly(true);
    btn_Search.setDisabled(true);

    if (!await scwin.selectMst() || !await scwin.selectIsu()) {
        scwin.lockButtons();
        return;
    }

    scwin.ensureRsnItem();
    scwin.savedState = scwin.getEditState();

    // 상장폐지일이 오늘 이후면 update(수정·삭제·안내문작성), 지났으면 error(처리 버튼 없음)
    $c.stf.setButtonSetWithDate(edt_DelistDd, false, "grpBtnBox", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.lockButtons
 * @author Inswave
 * @date 2026. 10. 29
 * @description 하단 처리 버튼을 모두 잠근다(로딩 중·조회 실패).
 * @returns
 * @hidden N
 */
scwin.lockButtons = function () {
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.searchNewIsu
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 조회. 기준일 8자리를 확인하고 대상종목 → 안내문구용 일자 순서로 조회해 상장폐지일·기타 안내문을 채운다.
 * 수정 모드에서는 하지 않는다(원본 [조회]·달력 잠금). (원본 fn_get_isu_cd + dts_Isu·dts_CheckDate OnLoadCompleted — §6.2)
 * @returns
 * @hidden N
 */
scwin.searchNewIsu = async function () {
    if (!scwin.isNew()) return;

    const baseDd = String(dma_search.get("baseDd") ?? "");
    if (baseDd.length !== 8) {
        // 원본 문구 그대로 — 라벨은 「현재일」 (§8 #3)
        await $c.win.alert("[최종거래일]을 정확히 입력하세요.");
        edt_Dd.focus();
        return;
    }

    if (!await scwin.selectNewIsu(baseDd)) return;
    if (!await scwin.selectLastTradingDayInfo(baseDd)) return;

    scwin.applyLastTradingDayInfo();
};

/**
 * @method
 * @name scwin.applyLastTradingDayInfo
 * @author Inswave
 * @date 2026. 10. 29
 * @description 안내문구용 일자 조회 결과로 상장폐지일과 기타 안내문을 채운다. 결과가 비면 상장폐지일은 비우고 안내문은 빈 표기로 만든다(원본과 같음). (원본 dts_CheckDate OnLoadCompleted — §6.3)
 * @returns
 * @hidden N
 */
scwin.applyLastTradingDayInfo = function () {
    dma_mst.set("remk", scwin.makeEtcInfo());
    dma_mst.set("delistDd", dma_lastTradingDayInfo.get("delistDd") ?? "");
};

/**
 * @method
 * @name scwin.makeEtcInfo
 * @author Inswave
 * @date 2026. 10. 29
 * @description 기타 안내문을 만든다 — 종목 수와 최종거래일·상장폐지일·권리행사기간 만료일 표기. (원본 fn_set_etc_info — §6.3)
 * @returns {String} 기타 안내문
 * @hidden N
 */
scwin.makeEtcInfo = function () {
    const lsttrdDdF = dma_lastTradingDayInfo.get("lsttrdDdF") ?? "";
    const delistDdF = dma_lastTradingDayInfo.get("delistDdF") ?? "";
    const exerEndDdF = dma_lastTradingDayInfo.get("exerEndDdF") ?? "";

    return "상기 " + dlt_isu.getRowCount() + "종목의 주식워런트증권은 최종거래일(" + lsttrdDdF + ")이 도래함에 따라 "
        + delistDdF + "에 \n상장폐지됨을 알려드립니다. (권리행사기간 만료일:" + exerEndDdF + ")";
};

/**
 * @method
 * @name scwin.applyGrndRegul
 * @author Inswave
 * @date 2026. 10. 29
 * @description 고른 상장폐지사유의 근거규정을 근거규정 입력란에 채운다. (원본 dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL") — §6.4)
 * @returns
 * @hidden N
 */
scwin.applyGrndRegul = function () {
    const code = dma_mst.get("delistRsnCd");
    const row = dlt_rsn.getAllJSON().find(item => item.code === code);
    dma_mst.set("grndRegulNm", row?.regl ?? "");
};

/**
 * @method
 * @name scwin.ensureRsnItem
 * @author Inswave
 * @date 2026. 10. 29
 * @description 수정 조회한 사유코드가 콤보 목록에 없으면 상세의 사유설명으로 한 항목을 더해 콤보가 비어 보이지 않게 한다.
 * 사유 목록 API 가 없어 목록이 고정값이기 때문이다(§10 #1). 근거규정은 조회 값을 그대로 둔다.
 * @returns
 * @hidden N
 */
scwin.ensureRsnItem = function () {
    const code = dma_mst.get("delistRsnCd");
    if ($c.util.isEmpty(code)) return;

    const list = dlt_rsn.getAllJSON();
    if (list.some(item => item.code === code)) return;

    list.push({ code : code, name : dma_mst.get("delistRsnDsc") || code, regl : dma_mst.get("grndRegulNm") });
    dlt_rsn.setJSON(list);
    dma_mst.set("delistRsnCd", code);   // 목록을 바꾼 뒤 콤보 선택을 다시 맞춘다
};

/**
 * @method
 * @name scwin.getEditState
 * @author Inswave
 * @date 2026. 10. 29
 * @description 입력값 스냅숏 — 상장폐지일·사유·근거규정·기타. 조회 직후 값과 비교해 저장하지 않은 변경을 찾는다. (원본 dts_Mst.IsUpdated || dts_Rsn.IsUpdated — §6.8)
 * @returns {String} 입력값 JSON 문자열
 * @hidden N
 */
scwin.getEditState = function () {
    return JSON.stringify([
        dma_mst.get("delistDd"),
        dma_mst.get("delistRsnCd"),
        dma_mst.get("grndRegulNm"),
        dma_mst.get("remk")
    ]);
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 29
 * @description 저장·수정 전 입력 검증. 원본 fn_CheckForm 순서를 따른다. (§6.1)
 *  1) 대상종목 1건 이상  2) 상장폐지일 필수·날짜, 익일 이후  3) 근거규정 필수·200 byte  4) 기타 2000 byte
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    if (dlt_isu.getRowCount() === 0) {
        await $c.win.alert("[상장폐지종목]을 선택하세요.");
        return false;
    }

    const dateOptions = {
        validateType : "alert",     // alert|mark|all
        checkType : "single",       // single|multi
        fields : {
            edt_DelistDd : { required : true, format : "date", name : "상장폐지일" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_3, dateOptions)) return false;

    // 상장폐지일은 익일 이후 (원본 checkDdTm("DD", …, "상장폐지", false) — pcc 함수는 Gauce 속성 .text 를 읽어 쓰지 않는다)
    if (dma_mst.get("delistDd") <= scwin.curDate) {
        await $c.win.alert("[상장폐지일]을 익일 이후로 입력하세요.");
        edt_DelistDd.focus();
        return false;
    }

    const textOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            txb_GrndRegulNm : { required : true, maxLengthB : 200, name : "근거규정" },
            txa_Remk : { maxLengthB : 2000, name : "기타" }
        }
    };
    return await $c.validate.validateDataCollect(panel_3, textOptions);
};

/**
 * @method
 * @name scwin.isComplete
 * @author Inswave
 * @date 2026. 10. 29
 * @description 등록·수정·삭제 성공 판정 — 응답 success 이고, 명세 처리 성공 여부(completeYn, boolean)가 false 가 아니면 성공이다. (§5, §10 #4)
 * @param {Object} result executeDynamic 결과
 * @returns {Boolean} 성공 여부
 * @hidden N
 */
scwin.isComplete = function (result) {
    if (!result?.responseJSON?.success) return false;
    return String(dma_result.get("completeYn") ?? "") !== "false";
};

/**
 * @method
 * @name scwin.getNewBzProcsNo
 * @author Inswave
 * @date 2026. 10. 29
 * @description 업무처리번호를 새로 받는다. $c.stf.getNewBzProcNo 는 응답 봉투를 그대로 돌려줄 수 있어 body 를 꺼내고,
 * body 가 문자열이면 그대로, 객체면 bzProcsNo 를 문자열로 만든다. 14자리 검사는 호출부(scwin.save)가 한다. (§5.5)
 * @returns {Promise<String>} 업무처리번호 (실패면 빈 문자열)
 * @hidden N
 */
scwin.getNewBzProcsNo = async function () {
    // TODO: 채번 응답 모양 미확정 — body 가 문자열인지 { bzProcsNo } 인지 확인 (§10 #3). 지금은 둘 다 받는다.
    const res = await $c.stf.getNewBzProcNo();
    const body = res?.body ?? res;
    return String((typeof body === "object" && body !== null) ? (body.bzProcsNo ?? "") : (body ?? ""));
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 저장. 검증 → 확인 → 채번 → 등록 순서. (원본 fn_save — §6.5, §1.4 업무 3)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;

    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const bzProcsNo = await scwin.getNewBzProcsNo();
    if (bzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }

    await scwin.saveTrs(scwin.trJob, bzProcsNo);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 29
 * @description 수정. 검증 → 확인 → 수정 순서. 원본처럼 바뀐 내용이 없어도 보낸다. (원본 fn_update — §6.6, §1.4 업무 4)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob, scwin.bzProcsNo);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 29
 * @description 삭제. 확인을 받은 뒤 삭제한다. 입력 검증은 하지 않는다. (원본 fn_delete — §6.7, §1.4 업무 5)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    scwin.trJob = "D";

    // "[삭제] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.deleteTrs();
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 29
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 fn_GetPar 로 채우던 arr[0..5] 와 데이터셋 2개다.
 * 마스터에는 원본처럼 상장폐지사유명(delistRsnNm, AS-IS DELIST_RSN_NM)을 콤보 표시값으로 더한다. (§6.8)
 * @returns {Object} 넘길 data
 * @hidden N
 */
scwin.getDsclData = function () {
    const mst = { ...dma_mst.getJSON(), delistRsnNm : cmb_Rsn_Cd.getText() };

    return {
        formCd : scwin.DSCL_FORM_CD,        // AS-IS arr[0]
        bzProcsNo : scwin.bzProcsNo,        // AS-IS arr[1]
        isurCd : scwin.ELW_ISUR_CD,         // AS-IS arr[2] "99999"
        mktId : scwin.DSCL_MKT_ID,          // AS-IS arr[3]
        msg : "",                           // AS-IS arr[4]
        title : scwin.DSCL_TITLE,           // AS-IS arr[5] 공시제목
        isu : dlt_isu.getAllJSON(),         // AS-IS CopyDataSet(dts_Isu, param_dts_isu)
        mst : [mst]                         // AS-IS CopyDataSet(dts_Mst, param_dts_mst)
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 29
 * @description 공시안내문작성. 조회 뒤 고친 입력이 있으면 수정 먼저 하라고 안내하고, 없으면 팝업을 data 로 넘겨 열고 닫힐 때까지 기다린다.
 * 원본도 닫힌 뒤 다시 조회하지 않는다. (원본 fn_dscl — §6.8, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.writeDscl = async function () {
    // MSG-0022 "변경된 항목이 있습니다. 수정후에 안내문작성을 다시 클릭하세요."
    if (scwin.getEditState() !== scwin.savedState) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }

    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 745,
        height : 820,
        type : "pageFramePopup"
    };

    // TODO: 경로는 가정, 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10 #7)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, scwin.getDsclData());
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 29
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (§6.8, §10 #7, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 발행기관코드 [3] 시장구분 [4] 메시지 [5] 공시제목 을 채운다
 * @param {Object} dltIsu 92024 의 종목 dataList
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @returns {Number} arr 길이
 * @hidden N
 */
scwin.getPar = function (arr, dltIsu, dltMst) {
    const data = scwin.getDsclData();

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;
    arr[4] = data.msg;
    arr[5] = data.title;

    scwin.fillDataList(dltIsu, data.isu);
    scwin.fillDataList(dltMst, data.mst);

    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 29
 * @description 컬럼 정의가 비어 있는 92024 의 원천 dataList 에 행 키를 컬럼으로 더하고 행을 채운다. (원본 CopyDataSet 의 헤더 복사 — §6.8)
 * @param {Object} dataList 채울 dataList
 * @param {Array} rows 행 배열
 * @returns
 * @hidden N
 */
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};
